<template><AppDialog :model-value="modelValue" title="定制我的学习面板" @update:model-value="emit('update:modelValue',$event)"><p class="workspace-caption">面板配置按当前账号保存在本机，不改变学习记录或服务器成绩。</p><form class="workspace-form widget-request" @submit.prevent="propose"><label class="m-field"><span>让星枢帮我添加面板</span><input v-model="request" class="m-input" maxlength="200" required placeholder="例如：把最近错题和待复习知识点放在首页" /></label><label class="m-field"><span>筛选目标（选填）</span><select v-model="goalId" class="m-input"><option value="">当前账号全部记录</option><option v-for="goal in store.workspace?.goals || []" :key="goal.id" :value="goal.id">{{ goal.title }}</option></select></label><button class="m-btn m-btn--primary m-btn--sm">生成安全面板预览</button></form><section v-if="preview" class="widget-preview" aria-live="polite"><span class="m-badge m-badge--info">本地规则匹配</span><h3>{{ preview.widget.title }}</h3><p>{{ preview.reason }}</p><p class="widget-content-preview">{{ contentPreview }}</p><dl><div><dt>内容</dt><dd>{{ widgetCatalog[preview.widget.kind].description }}</dd></div><div><dt>数据来源</dt><dd>{{ widgetCatalog[preview.widget.kind].source }}</dd></div><div><dt>权限</dt><dd>仅读取当前账号记录，无新增设备权限。</dd></div><div><dt>布局变化</dt><dd>新增一张面板，放在现有 {{ store.local.widgets.length }} 张之后。</dd></div></dl><label class="m-field"><span>面板标题</span><input v-model="preview.widget.title" class="m-input" maxlength="40" /></label><div class="workspace-actions"><button class="m-btn m-btn--primary m-btn--sm" @click="confirm">确认添加</button><button class="m-btn m-btn--ghost m-btn--sm" @click="preview = null">取消预览</button></div></section><p v-if="message" role="status" class="workspace-caption">{{ message }}</p><div class="workspace-section-head"><h3>当前面板与顺序</h3><span>{{ store.local.widgets.length }} / 12</span></div><ol class="widget-sort-list"><li v-for="(widget,index) in store.local.widgets" :key="widget.id"><div class="widget-sort-title"><label :for="`widget-title-${widget.id}`">{{ widgetCatalog[widget.kind].title }}</label><input :id="`widget-title-${widget.id}`" :value="widget.title" maxlength="40" class="m-input" @change="rename(widget.id,($event.target as HTMLInputElement).value)" /></div><div class="widget-sort-actions"><button class="icon-button" :aria-label="`上移${widget.title}`" :disabled="index===0" @click="move(index,-1)"><ArrowUp :size="16" /></button><button class="icon-button" :aria-label="`下移${widget.title}`" :disabled="index===store.local.widgets.length-1" @click="move(index,1)"><ArrowDown :size="16" /></button><button class="icon-button" :aria-label="`${widget.visible?'隐藏':'显示'}${widget.title}`" @click="toggle(widget.id)"><component :is="widget.visible?Eye:EyeOff" :size="16" /></button><button class="icon-button" :aria-label="`删除${widget.title}`" @click="remove(widget.id)"><Trash2 :size="16" /></button></div></li></ol><button v-if="!resetConfirm" class="workspace-text-action" @click="resetConfirm=true">恢复默认三个面板</button><div v-else class="workspace-confirm"><p>恢复默认排序和面板配置？不会清除学习记录。</p><button class="m-btn m-btn--ghost m-btn--sm" @click="store.setWidgets(defaultWidgets());resetConfirm=false">确认恢复默认</button></div></AppDialog></template>
<script setup lang="ts">
import { computed, ref } from 'vue'
import { ArrowDown, ArrowUp, Eye, EyeOff, Trash2 } from 'lucide-vue-next'
import AppDialog from './AppDialog.vue'
import { defaultWidgets, proposeWidget, validateWidget, widgetCatalog } from '@/mobile/domain/companion'
import { useLearningWorkspace } from '@/mobile/stores/learning-workspace'
defineProps<{modelValue:boolean}>();const emit=defineEmits<{'update:modelValue':[value:boolean]}>(),store=useLearningWorkspace(),request=ref(''),goalId=ref(''),preview=ref<ReturnType<typeof proposeWidget>|null>(null),message=ref(''),resetConfirm=ref(false)
const contentPreview=computed(()=>{const w=preview.value?.widget,ws=store.workspace;if(!w||!ws)return '记录尚未读取，请先连接学习工作区。';const tasks=store.taskItems.filter(t=>!w.goalId||t.goalId===w.goalId);switch(w.kind){case 'focus':return '开始一段 25 分钟计时，可暂停和恢复；可选择已保存的学习资料。';case 'tasks':return `${tasks.length} 项已确认学习清单，其中 ${tasks.filter(t=>t.done).length} 项自报完成。`;case 'review':return w.goalId?'错题暂无目标归属，需改为全部记录查看。':`${store.reviews.length} 道已完成练习中的错题，可打开原题与安排复习。`;case 'week':return '展示服务器已结束计时；未关联的练习不会混入特定目标。';case 'library':return w.goalId?'资料暂无目标归属，需改为全部记录查看。':`${ws.materials.length} 份私有资料，显示最近三份及原文入口。`;case 'goals':return `${ws.goals.filter(g=>!w.goalId||g.id===w.goalId).length} 个保存的长期目标。`;case 'agent':return `${ws.tasks.filter(t=>!w.goalId||t.goalId===w.goalId).length} 条星枢任务记录。`}})
function propose(){preview.value=proposeWidget(request.value,goalId.value||null);message.value=''}
function confirm(){if(!preview.value||!validateWidget(preview.value.widget))return;if(store.local.widgets.length>=12){message.value='最多保留 12 张面板，请先移除一张。';return}store.setWidgets([...store.local.widgets,{...preview.value.widget,id:crypto.randomUUID()}]);preview.value=null;message.value='面板已添加，并保存在本机。'}
function move(index:number,direction:number){const list=[...store.local.widgets];[list[index],list[index+direction]]=[list[index+direction]!,list[index]!];store.setWidgets(list)}
function toggle(id:string){store.setWidgets(store.local.widgets.map(w=>w.id===id?{...w,visible:!w.visible}:w))}
function rename(id:string,title:string){if(!title.trim())return;store.setWidgets(store.local.widgets.map(w=>w.id===id?{...w,title:title.trim().slice(0,40)}:w))}
function remove(id:string){store.setWidgets(store.local.widgets.filter(w=>w.id!==id))}
</script>
<style scoped>.widget-request{margin-top:20px;padding-bottom:22px;border-bottom:1px solid var(--m-border)}.widget-preview{padding:20px;border:1px solid var(--m-primary-border);border-radius:18px;background:var(--m-primary-soft)}.widget-preview h3{font-size:20px}.widget-preview p,.widget-preview dl{font-size:14px;line-height:1.8;color:var(--m-text-dim)}.widget-preview dl>div{display:grid;grid-template-columns:70px 1fr;gap:10px;margin:10px 0}.widget-preview dd{margin:0}.widget-preview dt{color:var(--m-text-faint)}.widget-sort-list{list-style:none;padding:0;margin:0}.widget-sort-list li{display:grid;gap:12px;padding:16px 0;border-bottom:1px solid var(--m-border)}.widget-sort-title label{display:block;color:var(--m-text-faint);font-size:12px;margin-bottom:8px}.widget-sort-actions{display:flex;gap:8px}.widget-sort-actions .icon-button{width:44px;height:44px}</style>
